@makeeno This is the workaround I use, not sure if that is helpful for your case.

```ts
export function getRequestUrl({ headers, nextUrl }: NextRequest): URL {
  // Extract protocol from x-forwarded-proto header or fallback to nextUrl protocol
  const protocol =
    headers.get("x-forwarded-proto") ||
    nextUrl.protocol.replace(/:$/, "");

  // Extract host from headers, prioritizing x-forwarded-host over host header
  const host =
    headers.get("x-forwarded-host") ||
    headers.get("host") ||
    null;

  if (host === null) {
    // Host header is mandatory per HTTP/1.1 spec (RFC 7230, RFC 9110)
    throw new Error("Missing HTTP request header 'Host'");
  }

  // Construct and return the URL object
  return new URL(
    `${protocol}://${host}${nextUrl.pathname}${nextUrl.search}${nextUrl.hash}`
  );
}
```

