Hook for routerstatereset

`/**
 * Custom hook that handles router state reset on route changes and browser navigation
 * @param routerInstanceRef - Ref object containing the router instance
 */
export const useRouterStateReset = (
  routerInstanceRef: RefObject<ReturnType<typeof createHeroFiltersRouter>>,
) => {
  useEffect(() => {
    const handleRouterStateReset = () => {
      if (routerInstanceRef.current) {
        // Check if we're still on a products page
        const currentPath = globalThis.location.pathname;
        const shouldResetPopState = isPageActive(currentPath, RoutesEnum.Products);

        resetRouterInstanceState(routerInstanceRef.current, shouldResetPopState);
      }
    };

    singletonRouter.events.on('routeChangeComplete', handleRouterStateReset);

    // Listen for popstate events (browser back/forward)
    globalThis.addEventListener('popstate', handleRouterStateReset);

    return () => {
      singletonRouter.events.off('routeChangeComplete', handleRouterStateReset);
      globalThis.removeEventListener('popstate', handleRouterStateReset);
    };
  }, [routerInstanceRef]);
};
`

utils ----
`export const resetRouterInstanceState = (
  router: ReturnType<typeof createHeroFiltersRouter>,
  shouldResetPopState: boolean,
) => {
  if (!router) return;

  setTimeout(() => {
    const routerWithPopState = router as RouterWithPopStateType;

    if (shouldResetPopState) {
      // Reset inPopState if it's true
      if (routerWithPopState.inPopState === true) {
        routerWithPopState.inPopState = false;
      }

      // Reset isDisposed if it's true
      if (routerWithPopState.isDisposed === true) {
        routerWithPopState.isDisposed = false;
      }
    }
  }, 100); // Small delay to ensure router state is updated
};`

