```tsx
'use client';
// eslint-disable-next-line no-restricted-imports
import NextLink from 'next/link';
import NProgress from 'nprogress';
import { useCallback, useEffect, useRef, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import { PrefetchKind } from 'next/dist/client/components/router-reducer/router-reducer-types';
import { useDebouncedCallback } from 'use-debounce';

const isModifiedClick = (e: React.MouseEvent) => {
    return e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0;
};

type LinkProps = {
    hideProgressBar?: boolean;
    preventNavigation?: boolean;
    stopPropagation?: boolean;
} & Parameters<typeof NextLink>[0];

export default function Link({ hideProgressBar, preventNavigation, stopPropagation, ...props }: LinkProps) {
    const router = useRouter();

    const [isPending, startTransition] = useTransition();
    const isPrefetched = useRef(false);

    useEffect(() => {
        if (hideProgressBar) return;
        if (isPending) {
            NProgress.start();
        } else {
            NProgress.done();
        }
    }, [isPending, hideProgressBar]);

    const prefetch = useCallback(() => {
        if (isPrefetched.current || props.target === '_blank' || preventNavigation) return;

        isPrefetched.current = true;
        router.prefetch(props.href.toString(), {
            kind: PrefetchKind.FULL,
        });
    }, [props.target, preventNavigation, props.href.toString()]);

    const debouncedPrefetch = useDebouncedCallback(prefetch, 50);

    return (
        <NextLink
            {...props}
            prefetch={false}
            onMouseEnter={e => {
                props.onMouseEnter?.(e);
                debouncedPrefetch();
            }}
            onMouseLeave={e => {
                props.onMouseLeave?.(e);
                debouncedPrefetch.cancel();
            }}
            onClick={e => {
                props.onClick?.(e);

                if (props.target === '_blank' || isModifiedClick(e)) {
                    return;
                }

                e.preventDefault();

                if (preventNavigation) return;
                if (stopPropagation) e.stopPropagation();

                startTransition(() => {
                    const url = props.href.toString();
                    const options = {
                        scroll: props.scroll ?? true,
                    };

                    if (props.replace) {
                        router.replace(url, options);
                    } else {
                        router.push(url, options);
                    }
                });
            }}
        >
            {props.children}
        </NextLink>
    );
}

```

