```tsx
"use client";
import { ReactNode, Fragment, useEffect } from "react";

const componentKey = { val: 0 };
export function ResetStateOnUnmount(props: { children: ReactNode }) {
  useEffect(() => {
    return () => {
      componentKey.val++;
