We hit this same race in production (education SaaS, Next.js **16.2.6 stable**) and independently root-caused it to the action queue before finding this issue. Posting our analysis since it adds a deterministic non-browser reproduction, a precise mechanism trace, and notes on the fix shape — we've been running a workaround in production via patch-package for the past week.

## Mechanism (one level below the breakpoint trace in the description)

When a navigation supersedes an in-flight server action, `dispatchAction` marks the pending action `discarded` and starts the navigation immediately, inheriting the discarded action's queue tail. But in `runAction` (`app-router-instance.ts`), the **discarded** action's `handleResult` — and the rejection callback — still call `runRemainingActions` **unconditionally** when the action settles. At that moment the discarded action is *not* the queue head (the navigation is), so if it settles while the navigation's RSC fetch is still in flight, `runRemainingActions` advances `actionQueue.pending` **past the running navigation** and starts the next queued action with `prevState = actionQueue.state` — the **pre-navigation** state. (It also means two queue entries are now effectively running concurrently, and the navigation's own completion advances the queue a second time.)

When that stale-seeded action later resolves, every completion path in `server-action-reducer` propagates its captured state (the no-revalidation path literally `return state`), its `handleResult` writes `actionQueue.state = <pre-navigation state>`, and because its deferred promise is React's latest router-state promise, React commits the old `canonicalUrl`. The user silently "bounces back" to the previous page seconds after a successful navigation — no error, no redirect, no log. Retrying always works (a fresh navigation re-captures state), which makes it look random and unreportable.

## Real-world impact

In our app every React Query fetch is a server action, so several are commonly in flight at page mount. Before we patched, analytics found **39 no-click A→B→A URL reverts in 14 days** across users. The race window scales with server-action latency, which is consistent with the slow-4G repro reported above.

## Deterministic reproduction (no browser)

This drives the queue logic copied verbatim from `app-router-instance.js` (16.1.6 — the relevant logic is unchanged in 16.2.6) with the timeline: slow action S1 in flight → `router.push` navigation N (marks S1 discarded, inherits S2) → S1 settles mid-navigation → S2 starts with pre-navigation state → N commits correctly → S2 resolves and re-commits the pre-navigation `canonicalUrl`. Reproduces on every run:

```
t+ 927ms  [REACT COMMIT] canonicalUrl = /dashboard/classes/CLASS-X  (from N)
...
t+3608ms  [reducer] ACTION S4(any later query) STARTS — captured state.canonicalUrl = /dashboard/classes/my-classes   <-- POSTs to this URL
t+3912ms  [REACT COMMIT] canonicalUrl = /dashboard/classes/my-classes  (from S4(any later query))

*** BUG REPRODUCED: user navigated to CLASS-X but ended up back on my-classes ***
```

<details>
<summary><code>queue-race-sim.mjs</code> — run with <code>node queue-race-sim.mjs</code></summary>

```js
// Deterministic simulation of the Next.js 16.1.6 action-queue race.
// dispatchAction / runAction / runRemainingActions are copied VERBATIM
// (modulo module plumbing) from
// node_modules/next/dist/client/components/app-router-instance.js.
// The reducer is a stub that mimics the timing behavior of
// navigateReducer / serverActionReducer: async, captures `state`, resolves later.

const ACTION_NAVIGATE = 'navigate'
const ACTION_RESTORE = 'restore'
const ACTION_SERVER_ACTION = 'server-action'

const log = []
const t0 = Date.now()
const now = () => `t+${String(Date.now() - t0).padStart(4)}ms`

// ---- verbatim queue logic (16.1.6) ----
function runRemainingActions(actionQueue, setState) {
  if (actionQueue.pending !== null) {
    actionQueue.pending = actionQueue.pending.next
    if (actionQueue.pending !== null) {
      runAction({ actionQueue, action: actionQueue.pending, setState })
    }
  } else {
    if (actionQueue.needsRefresh) {
      actionQueue.needsRefresh = false
      actionQueue.dispatch({ type: 'refresh' }, setState)
    }
  }
}

async function runAction({ actionQueue, action, setState }) {
  const prevState = actionQueue.state
  actionQueue.pending = action
  const payload = action.payload
  const actionResult = actionQueue.action(prevState, payload)
  function handleResult(nextState) {
    if (action.discarded) {
      if (action.payload.type === ACTION_SERVER_ACTION && action.payload.didRevalidate) {
        actionQueue.needsRefresh = true
      }
      runRemainingActions(actionQueue, setState)
      return
    }
    actionQueue.state = nextState
    runRemainingActions(actionQueue, setState)
    action.resolve(nextState)
  }
  if (typeof actionResult?.then === 'function') {
    actionResult.then(handleResult, (err) => {
      runRemainingActions(actionQueue, setState)
      action.reject(err)
    })
  } else {
    handleResult(actionResult)
  }
}

function dispatchAction(actionQueue, payload, setState) {
  let resolvers = { resolve: setState, reject: () => {} }
  if (payload.type !== ACTION_RESTORE) {
    const deferredPromise = new Promise((resolve, reject) => {
      resolvers = { resolve, reject }
    })
    // startTransition(() => setState(deferredPromise))  -- React side:
    setState(deferredPromise, payload.name)
  }
  const newAction = { payload, next: null, resolve: resolvers.resolve, reject: resolvers.reject }
  if (actionQueue.pending === null) {
    actionQueue.last = newAction
    runAction({ actionQueue, action: newAction, setState })
  } else if (payload.type === ACTION_NAVIGATE || payload.type === ACTION_RESTORE) {
    actionQueue.pending.discarded = true
    newAction.next = actionQueue.pending.next
    runAction({ actionQueue, action: newAction, setState })
  } else {
    if (actionQueue.last !== null) {
      actionQueue.last.next = newAction
    }
    actionQueue.last = newAction
  }
}

// ---- reducer stub mimicking real reducers' state capture + async timing ----
const sleep = (ms) => new Promise(r => setTimeout(r, ms))

function reducer(state, payload) {
  // mimics: serverActionReducer / navigateReducer capture `state` at start
  if (payload.type === ACTION_NAVIGATE) {
    return (async () => {
      await sleep(payload.fetchMs) // fetchServerResponse (RSC shell)
      log.push(`${now()}  [reducer] NAVIGATE ${payload.url} resolves (captured base=${state.canonicalUrl})`)
      return { canonicalUrl: payload.url, tree: payload.url }
    })()
  }
  if (payload.type === ACTION_SERVER_ACTION) {
    return (async () => {
      log.push(`${now()}  [reducer] ACTION ${payload.name} STARTS — captured state.canonicalUrl = ${state.canonicalUrl}   <-- POSTs to this URL`)
      await sleep(payload.fetchMs)
      log.push(`${now()}  [reducer] ACTION ${payload.name} resolves`)
      if (payload.didRevalidate) {
        // server-action-reducer.js:264-301 — navigate to captured canonicalUrl
        return { canonicalUrl: state.canonicalUrl, tree: state.tree, via: `navigate-after-${payload.name}` }
      }
      // bail-out (line 240-247): "return state" — the CAPTURED state object
      return state
    })()
  }
  if (payload.type === 'refresh') {
    return (async () => {
      await sleep(50)
      return { ...state, via: 'refresh' }
    })()
  }
}

// ---- React side: latest dispatched promise wins (useState semantics) ----
let latestPromise = null
let committed = { canonicalUrl: '/dashboard/classes/my-classes', tree: 'my-classes' }
function setState(p, name) {
  latestPromise = p
  const mine = p
  Promise.resolve(p).then((s) => {
