      committed = s
      log.push(`${now()}  [REACT COMMIT] canonicalUrl = ${s.canonicalUrl}  (from ${name ?? 'action'}${s.via ? ', via ' + s.via : ''})  ==> HistoryUpdater pushes/replaces URL`)
    }
  })
}

const actionQueue = {
  state: { canonicalUrl: '/dashboard/classes/my-classes', tree: 'my-classes' },
  dispatch: (payload, ss) => dispatchAction(actionQueue, payload, ss),
  action: (state, payload) => reducer(state, payload),
  pending: null,
  last: null,
  needsRefresh: false,
}

// ---- Repro timeline ----
// t=0     my-classes page mounts; two React Query server-action queries fire
