```js
// next.config.ts
import type { NextConfig } from "next";
import createMDX from "@next/mdx";

const nextConfig: NextConfig = {
  pageExtensions: ["js", "jsx", "md", "mdx", "ts", "tsx"],
  webpack(config, { isServer }) {
    if (!isServer) return config;

    const RSC_LAYER = "rsc"; // WEBPACK_LAYERS.reactServerComponents

    const matchesMdx = (test: unknown): boolean =>
      test instanceof RegExp && test.test("page.mdx");

    const isSwcLoader = (entry: unknown): entry is { options: Record<string, unknown> } =>
      !!entry &&
      typeof entry === "object" &&
      typeof (entry as { loader?: unknown }).loader === "string" &&
      (entry as { loader: string }).loader.includes("next-swc-loader");

    const patch = (rules: unknown[]): void => {
      for (const rule of rules) {
        if (!rule || typeof rule !== "object") continue;
        const r = rule as Record<string, unknown>;

        if (matchesMdx(r.test)) {
          const uses = Array.isArray(r.use) ? r.use : [r.use];
          for (const entry of uses) {
            if (isSwcLoader(entry) && entry.options.bundleLayer == null) {
              entry.options.bundleLayer = RSC_LAYER;
            }
          }
        }

        if (Array.isArray(r.oneOf)) patch(r.oneOf);
        if (Array.isArray(r.rules)) patch(r.rules);
      }
    };

    if (Array.isArray(config.module?.rules)) patch(config.module.rules);

    return config;
  },
};

const withMDX = createMDX({});

export default withMDX(nextConfig);
```

### Additional finding: Static import workaround does NOT fix the issue

I initially tried switching from a dynamic `import()` to a **static import** for the default locale, thinking Turbopack would then be able to track the file in its module graph:

```typescript
// Static import for default locale
import enMessages from '../../messages/en.json';

const importLocale = async (locale: Locale): Promise<Messages> => {
  if (locale === 'en') {
    return enMessages; // use static import
  }
  return (await import(`../../messages/${locale}.json`)).default;
};
```

This does **not** fix the issue — HMR still stops after the first edit even with a static import for `en.json`. So the problem is not limited to dynamic `import()` with template literals; it also affects statically imported JSON files consumed by `next-intl`'s `getRequestConfig`.

This further suggests the regression is in Turbopack's Server Fast Refresh module invalidation chain, not just in how it resolves dynamic imports.

