  // 生产环境始终过滤内部头，忽略测试标志
  filterInternalHeaders(req.headers)
} else if (!process.env.NEXT_PRIVATE_TEST_HEADERS) {
  filterInternalHeaders(req.headers)
} else {
  console.warn(
    '[Warning] NEXT_PRIVATE_TEST_HEADERS is set. Internal header filtering is disabled. ' +
    'This should only be used in test environments.'
  )
}
```

### 方案二：添加启动时警告

在服务器启动时检测并警告：

```typescript
