      'This disables internal header filtering and creates a security vulnerability. ' +
      'Remove this environment variable immediately.'
    )
    // 可选：直接退出进程
    // process.exit(1)
  } else {
    console.warn(
      '[Warning] NEXT_PRIVATE_TEST_HEADERS is set. Internal header filtering is disabled.'
    )
  }
}
```

### 方案三：更安全的测试标志设计

将测试标志改为白名单模式，只允许指定的测试头通过：

```typescript
// 定义允许通过的测试头列表
